pub fn largest<T: PartialOrd + Copy>(xs: &[T]) -> Option<T> {
    let mut it = xs.iter();
    let mut best = *it.next()?;
    for x in it {
        if *x > best {
            best = *x;
        }
    }
    Some(best)
}

